"use client";

import { useUser, useAuth } from "@clerk/nextjs";
import { useRouter } from "next/navigation";
import Image from "next/image";

export default function ProfilePage() {
  const { user, isLoaded } = useUser();
  const { signOut } = useAuth();
  const router = useRouter();

  if (!isLoaded) {
    return (
      <div className="min-h-screen bg-[#121212] flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#FFD700]"></div>
      </div>
    );
  }

  if (!user) {
    router.push("/sign-in");
    return null;
  }

  return (
    <div className="min-h-screen bg-[#121212] text-white">
      <div className="px-6 pb-8 pt-6">
        <div className="bg-[#282828] rounded-3xl p-6">
          <div className="flex items-center">
            <div className="relative">
              {user.imageUrl ? (
                <Image
                  src={user.imageUrl}
                  alt={user.fullName || "User"}
                  width={80}
                  height={80}
                  className="rounded-full"
                  unoptimized
                />
              ) : (
                <div className="bg-[#282828] rounded-full w-20 h-20 flex items-center justify-center">
                  <span className="text-4xl">👤</span>
                </div>
              )}
              <div className="absolute -bottom-1 -right-1 bg-[#FFD700] rounded-full w-7 h-7 flex items-center justify-center border-2 border-[#282828]">
                <span className="text-[#121212] text-xs">✓</span>
              </div>
            </div>

            <div className="flex-1 ml-4">
              <h1 className="text-white text-2xl font-bold mb-1">
                {user.fullName || `${user.firstName || ""} ${user.lastName || ""}`.trim() || "Χρήστης"}
              </h1>
              <p className="text-[#B3B3B3] text-sm">
                {user.emailAddresses?.[0]?.emailAddress || "Χωρίς email"}
              </p>
            </div>
          </div>
        </div>
      </div>

      <div className="px-6 space-y-3">
        <button
          onClick={() => router.push("/cart")}
          className="w-full bg-[#282828] rounded-2xl p-4 flex items-center justify-between hover:bg-[#3E3E3E] transition-colors"
        >
          <div className="flex items-center">
            <span className="text-2xl mr-3">🛒</span>
            <span className="text-white font-semibold">Καλάθι</span>
          </div>
          <span className="text-[#666]">→</span>
        </button>

        <button
          onClick={() => signOut(() => router.push("/"))}
          className="w-full bg-[#282828] rounded-2xl py-5 flex items-center justify-center border-2 border-red-500/20 hover:bg-red-500/10 transition-colors"
        >
          <span className="text-red-500 font-bold text-base">Αποσύνδεση</span>
        </button>
      </div>
    </div>
  );
}
